package dev.waylus

import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Test

class Lz4Test {
    /** The test input of [hostVector]: a ramp, a repeated phrase, a run of 0xff. */
    private fun sample(): ByteArray {
        val out = java.io.ByteArrayOutputStream()
        for (i in 0 until 3000) out.write((i * 7 / 13) % 251)
        repeat(40) { out.write("hello world ".toByteArray()) }
        repeat(700) { out.write(0xff) }
        return out.toByteArray()
    }

    @Test
    fun decodesHostOutput() {
        // lz4_flex 0.14 block::compress(sample()), as the host sends it.
        val hex = ""
        val c = ByteArray(hex.length / 2) { hex.substring(it * 2, it * 2 + 2).toInt(16).toByte() }
        val want = sample()
        val got = ByteArray(want.size)
        assertEquals(want.size, Lz4.decompress(c, 0, c.size, got, 0, got.size))
        assertArrayEquals(want, got)
    }

    @Test
    fun roundTrip() {
        val r = java.util.Random(1)
        for (data in listOf(sample(), ByteArray(0), ByteArray(5) { 1 }, ByteArray(70_000) { (r.nextInt(4)).toByte() }, ByteArray(9000).also { r.nextBytes(it) })) {
            val c = Lz4.compress(data)
            val got = ByteArray(data.size)
            assertEquals(data.size, Lz4.decompress(c, 0, c.size, got, 0, got.size))
            assertArrayEquals(data, got)
        }
    }

    @Test(expected = IllegalArgumentException::class)
    fun rejectsBadOffset() {
        // One sequence: no literals, match offset 9 into an empty output.
        val bad = byteArrayOf(0x00, 9, 0, 0x10, 'x'.code.toByte())
        Lz4.decompress(bad, 0, bad.size, ByteArray(64), 0, 64)
    }
}
